const std=@import("std");const M=@import("simulation/microbes.zig");const S=@import("simulation/shared_soil.zig");const C=@import("climate_fixtures.zig");
const State=struct{cell:M.Cell=. { .nutrient=0.02 },soil:f64=0.7101186234866845,vapor:f64=1,air:f32=0.2,oxygen:f32=0.2,recovery:f32=0,paid:f64=0,entries:u32=0,wakes:u32=0,inactive_ticks:u32=0};
fn enter(s:*State,i:usize)bool{const c=&s.cell.cohorts[i];if(c.inactive or c.biomass<=0)return false;const after=c.biomass*0.98;const debit=c.biomass-after;if(debit<=0 or debit>s.oxygen or after<0.0025)return false;const ratio=after/c.biomass;c.biomass=after;c.support_mass*=ratio;c.inactive=true;s.air+=debit;s.oxygen-=debit;s.cell.nutrient+=debit*M.nutrient_per_carbon;s.paid+=debit;s.entries+=1;s.recovery=0;return true;}
fn control(s:*State,i:usize,e:M.Environment)bool{const c=&s.cell.cohorts[i];if(c.biomass<=0){s.recovery=0;return false;}if(!c.inactive){if(e.temperature<278 or e.temperature>323 or e.depth_km==0)_=enter(s,i);return false;}if(e.temperature>=283 and e.temperature<=318 and e.depth_km>0)s.recovery+=1440 else s.recovery=0;return s.recovery>=7200;}
fn run(kind:usize,slot:usize)!void{var s:State=.{};s.cell.cohorts[slot]=C.phenotypes[0];s.cell.cohorts[1-slot]=C.phenotypes[0];s.cell.cohorts[1-slot].lineage+=10000;const ci=@as(f64,M.carbon(s.cell))+s.air;const ni=M.nutrientTotal(s.cell);if(kind==5)try std.testing.expect(enter(&s,slot));
 for(0..420)|tick|{const phase=@as(f64,@floatFromInt(tick%60))/60;var e=M.Environment{.temperature=@floatCast(298+2*@sin(2*std.math.pi*phase)),.depth_km=0.0000005,.light=@floatCast(@max(@as(f64,0),@sin(2*std.math.pi*phase))),.carbon_available=s.air,.oxygen_carbon_capacity=s.oxygen,.immersion_physiology=true,.final_demand_physiology=true};
 if(kind==1 and tick>=60 and tick<120)e.depth_km=0;if(kind==2 and tick>=60 and tick<120)e.temperature=263;if(kind==3)e.temperature=240;if(kind==4)e.temperature=400;
 const wake=control(&s,slot,e);e.carbon_available=s.air;e.oxygen_carbon_capacity=s.oxygen;
 const water=S.stepBorrowed(&s.cell,s.soil,s.vapor,7.6695296e9,e,1440,10,0).?;s.soil=water.soil;s.vapor=water.vapor;e.root_credit=water.credits;for(s.cell.cohorts,0..)|c,i|e.root_owner[i]=c.lineage;
 if(s.cell.cohorts[slot].inactive){s.inactive_ticks+=1;try std.testing.expectEqual(@as(f64,0),water.credits[slot]);}
 const f=M.step(&s.cell,e,1440);s.air=s.air-f.fixed+f.recycled;s.oxygen=s.oxygen+f.fixed-f.recycled;
 if(wake and s.cell.cohorts[slot].biomass>0){s.cell.cohorts[slot].inactive=false;s.wakes+=1;s.recovery=0;}
 try std.testing.expect(s.air>=0 and s.oxygen>=0 and s.soil>=0 and s.soil<=0.7101186234866845);try std.testing.expectApproxEqAbs(ci,@as(f64,M.carbon(s.cell))+s.air,0.00001);try std.testing.expectApproxEqAbs(ni,M.nutrientTotal(s.cell),0.00001);
 if((tick+1)%60==0)std.debug.print("DAY kind={} slot={} day={} protected={d} active={d} paid={d} entries={} wakes={} inactive_ticks={} soil={d}\n",.{kind,slot,(tick+1)/60,s.cell.cohorts[slot].biomass,s.cell.cohorts[1-slot].biomass,s.paid,s.entries,s.wakes,s.inactive_ticks,s.soil});
 }
}
test "fixed protective inactivity shared finite resource matrix" {for(0..6)|k|for(0..2)|slot|try run(k,slot);}
test "inactive finite accounting entry refusal and actual edibility" {var s:State=.{};s.cell.cohorts[0]=C.phenotypes[0];s.oxygen=0;const old=s;try std.testing.expect(!enter(&s,0));try std.testing.expectEqualDeep(old,s);s.oxygen=1;try std.testing.expect(enter(&s,0));const e=M.Environment{.temperature=298,.depth_km=0.001,.light=1,.carbon_available=1,.oxygen_carbon_capacity=1};try std.testing.expectEqual(@as(f64,0),M.rootDemand(s.cell.cohorts[0],e,1440));s.cell.cohorts[0].feeding=1;s.cell.cohorts[0].reproduction_credit=1;var dest=M.initialized(10);var stats:M.Stats=.{};try std.testing.expect(!M.propagate(&s.cell,0,&dest,&stats));const f=M.step(&s.cell,e,1440);try std.testing.expectEqual(@as(f32,0),f.fixed);s.cell.cohorts[1]=.{.biomass=0.1,.lineage=999,.feeding=1};const before=s.cell.cohorts[0].biomass;const g=M.graze(&s.cell,0.1,1);try std.testing.expect(g.consumed>0 and s.cell.cohorts[0].biomass<before);}
test "recovery requires continuous two hours and cannot resurrect" {var s:State=.{};s.cell.cohorts[0]=C.phenotypes[0];try std.testing.expect(enter(&s,0));var e=M.Environment{.temperature=298,.depth_km=0.001,.light=1,.carbon_available=1,.oxygen_carbon_capacity=1};for(0..4)|_|try std.testing.expect(!control(&s,0,e));e.temperature=263;try std.testing.expect(!control(&s,0,e));try std.testing.expectEqual(@as(f32,0),s.recovery);e.temperature=298;for(0..4)|_|try std.testing.expect(!control(&s,0,e));try std.testing.expect(control(&s,0,e));s.cell.cohorts[0]=.{};try std.testing.expect(!control(&s,0,e));try std.testing.expect(!enter(&s,0));}
